#!/usr/bin/perl
use strict;
use warnings;

# ArithmeticEncoder class
package ArithmeticEncoder;

sub new {
    my $class = shift;
    my $self = {
        radix => 255,
        range => 1,
        low => 0,
        output => [],
        cc => {}
    };
    bless $self, $class;
    return $self;
}

sub get_counts {
    my ($self, $ctx) = @_;
    if (!exists $self->{cc}{$ctx}) {
        $self->{cc}{$ctx} = [0, 0];
    }
    return $self->{cc}{$ctx};
}

sub put_bit {
    my ($self, $bit, $ctx) = @_;

    # Normalize if range gets too small
    while ($self->{range} < $self->{radix}) {
        push @{$self->{output}}, int($self->{low} / $self->{radix}) + 1;
        $self->{low} = ($self->{low} % $self->{radix}) * $self->{radix};
        $self->{range} *= $self->{radix};
    }

    my $counts = $self->get_counts($ctx);
    my $split = int($self->{range} * ($counts->[0] + 1) / ($counts->[0] + $counts->[1] + 2));

    if ($bit) {
        $self->{low} += $split;
        $self->{range} -= $split;
    } else {
        $self->{range} = $split;
    }

    $counts->[$bit] += 1;
}

sub put_integer {
    my ($self, $value, $tmp, $ctx) = @_;

    my $subtract_it = 1 << $tmp;
    my $encoded_value = $value + $subtract_it;

    # Find the bit length
    my $bit_len = 0;
    my $temp = $encoded_value;
    while ($temp > 0) {
        $bit_len++;
        $temp >>= 1;
    }
    $bit_len -= 1;

    $ctx *= 99;
    # Encode unary: bit_len zeros followed by a one
    for (my $i = 0; $i < $bit_len; $i++) {
        $self->put_bit(0, $tmp + 1 + $i + $ctx);
    }
    $self->put_bit(1, $tmp + 1 + $bit_len + $ctx);

    # Encode the bits from high to low (excluding the leading 1)
    for (my $i = $bit_len - 1; $i >= 0; $i--) {
        my $bit_val = ($encoded_value >> $i) & 1;
        $self->put_bit($bit_val, $ctx);
    }
}

sub flush {
    my $self = shift;

    # Output enough to disambiguate
    for (my $i = 0; $i < 10; $i++) {
        push @{$self->{output}}, int($self->{low} / $self->{radix}) + 1;
        $self->{low} = ($self->{low} % $self->{radix}) * $self->{radix};
    }

    return pack('C*', @{$self->{output}});
}

package main;

sub find_matches {
    my ($data, $pos, $max_offset, $max_len) = @_;
    $max_offset //= 31;
    $max_len //= 7;

    return (undef, 0) if $pos == 0;

    my $best_len = 0;
    my $best_offset = 0;

    # Search backward for matches
    my $search_start = $pos - $max_offset;
    $search_start = 0 if $search_start < 0;

    for (my $offset = 1; $offset <= $pos - $search_start && $offset <= $max_offset; $offset++) {
        my $match_pos = $pos - $offset;
        last if $match_pos < 0;

        # Check how long the match is
        my $match_len = 0;
        while ($match_len < $max_len && 
               $pos + $match_len < length($data) &&
               substr($data, $match_pos + $match_len, 1) eq substr($data, $pos + $match_len, 1)) {
            $match_len++;
        }

        if ($match_len > $best_len) {
            $best_len = $match_len;
            $best_offset = $offset;
        }
    }

    # Only return match if it's worth encoding (length >= 2)
    if ($best_len >= 2) {
        return ($best_offset, $best_len);
    }
    return (undef, 0);
}

sub compress {
    my ($input_text) = @_;

    # Build operation list
    my @operations = ();
    my $pos = 0;
    my $data_len = length($input_text);

    while ($pos < $data_len) {
        my ($offset, $length) = find_matches($input_text, $pos, 31, 7);

        if (defined $offset) {
            # Back-reference
            push @operations, ['ref', $offset - 1, $length - 1];
            $pos += $length;
        } else {
            # Literal
            my $char_val = ord(substr($input_text, $pos, 1));
            if ($char_val > 127) {
                $char_val = $char_val - 256;  # Convert to signed
            }
            push @operations, ['lit', $char_val];
            $pos += 1;
        }
    }

    # Encode
    my $encoder = ArithmeticEncoder->new();

    # Encode number of operations
    $encoder->put_integer(scalar @operations, 9, 0);

    # Encode each operation
    foreach my $op (@operations) {
        if ($op->[0] eq 'ref') {
            # Back-reference
            $encoder->put_bit(1, 1);
            $encoder->put_integer($op->[1], 5, 2);  # OFF1=5, ctx=2
            $encoder->put_integer($op->[2], 2, 3);  # OFF2=2, ctx=3
        } else {
            # Literal
            $encoder->put_bit(0, 1);
            my $char_val = $op->[1];
            if ($char_val < 0) {
                $encoder->put_bit(1, 8);  # sign bit
                $encoder->put_integer(-$char_val, 4, 9);
            } else {
                $encoder->put_bit(0, 8);  # sign bit
                $encoder->put_integer($char_val, 4, 9);
            }
        }
    }

    return $encoder->flush();
}

# Main
open(my $fh, '<', '/app/data.txt') or die "Cannot open data.txt: $!";
my $input_text = do { local $/; <$fh> };
close($fh);

my $compressed = compress($input_text);

open(my $out, '>', '/app/data.comp') or die "Cannot write data.comp: $!";
binmode($out);
print $out $compressed;
close($out);

print "Compressed ", length($input_text), " bytes to ", length($compressed), " bytes\n";
print "Compression ratio: ", sprintf("%.1f", length($compressed) / length($input_text) * 100), "%\n";

