#!/usr/bin/perl
use strict;
use warnings;

# Minimal encoder to test basic protocol
# Goal: encode just "Hi" (2 literals) to verify arithmetic coding works

my $RADIX = 255;
my $OFF1 = 5;
my $OFF2 = 2; 
my $LITSIZE = 4;

my @output;
my $low = 0;
my $range = 1;  # Match decoder initialization
my %counts;

sub output_byte {
    my ($val) = @_;
    $val = 255 if $val > 255;
    $val = 1 if $val < 1;
    push @output, $val;
}

sub normalize {
    while ($range < $RADIX) {
        my $val = int($low / $RADIX) + 1;
        output_byte($val);
        $low = ($low % $RADIX) * $RADIX;
        $range *= $RADIX;
    }
}

sub put_bit {
    my ($bit, $ctx) = @_;
    normalize();

    $counts{$ctx} = [0, 0] unless exists $counts{$ctx};
    my $c = $counts{$ctx};

    my $split = int($range * ($c->[0] + 1) / ($c->[0] + $c->[1] + 2));

    if ($bit) {
        $low += $split;
        $range -= $split;
        $c->[1]++;
    } else {
        $range = $split;
        $c->[0]++;
    }
}

sub put_integer {
    my ($value, $off, $ctx) = @_;

    my $tmp = 0;
    $tmp++ while ((1 << $tmp) <= $value);

    my $encoded = $value + (1 << $tmp);

    # Encode bit_len in unary
    for my $i (0 .. $tmp - 1) {
        put_bit(1, $ctx * 99 + $i + 1);
    }
    put_bit(0, $ctx * 99 + $tmp + 1);

    # Encode magnitude in binary
    for (my $i = $tmp - 1; $i >= 0; $i--) {
        put_bit(($encoded >> $i) & 1, $ctx);
    }
}

sub flush {
    for (1..10) {
        my $val = int($low / $RADIX) + 1;
        output_byte($val);
        $low = ($low % $RADIX) * $RADIX;
    }
}

# Encode "Hi" as 2 literal operations
# Operation count: 2
put_integer(2, 9, 0);

# Operation 1: literal 'H' (72)
put_bit(0, 1);  # op type = literal
put_bit(0, 8);  # sign = positive
put_integer(72, $LITSIZE, 9);  # magnitude

# Operation 2: literal 'i' (105)
put_bit(0, 1);  # op type = literal  
put_bit(0, 8);  # sign = positive
put_integer(105, $LITSIZE, 9);  # magnitude

flush();

print pack('C*', @output);

print STDERR "Generated " . scalar(@output) . " bytes\n";

