#include <stdio.h>

int radix = 255, fraction, range = 1;
#define LITSIZE 4
#define OFF1 5
#define OFF2 2
int counts[1000000];

int main() {
    char buffer[10000] = {0};
    int pos = 0;

    // Read operation count
    int tmp = 0, ctx = 0;
    int subtract_it = (1 << tmp);
    int result_ans = 1;
    ctx *= 99;

    fprintf(stderr, "Starting decoder...\n");
    fprintf(stderr, "Initial range=%d, fraction=%d\n", range, fraction);

    // Try to read first few bytes
    for(int i = 0; i < 20; i++) {
        int c = getchar();
        if(c == EOF) {
            fprintf(stderr, "EOF at byte %d\n", i);
            break;
        }
        fprintf(stderr, "Byte %d: %d (0x%02x)\n", i, c, c);
    }

    return 0;
}
EOFDECOMP

