arguments.script:
# Create a minimal test - single character 'A'
echo -n 'A' > test_single.txt

# Compile encoder with added debug output
cat > encoder_debug.c << 'EEOF'
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define RADIX 255
#define OFF1 5
#define OFF2 2
#define LITSIZE 4

int cc[1000000];
long long low = 0, range = 1;

void normalize() {
    while (range < RADIX) {
        int byte_out = (low / RADIX) + 1;
        if (byte_out > 255) byte_out = 255;
        fprintf(stderr, "NORM: output byte=%d, low=%lld, range=%lld\n", byte_out, low, range);
        putchar(byte_out);
        low = (low % RADIX) * RADIX;
        range *= RADIX;
    }
}

void put_bit(int bit, int ctx) {
    normalize();
    int *counts = &cc[ctx * 2];
    long long split = range * (counts[0] + 1) / (counts[0] + counts[1] + 2);
    fprintf(stderr, "PUT_BIT: bit=%d ctx=%d counts=[%d,%d] split=%lld range=%lld\n", 
            bit, ctx, counts[0], counts[1], split, range);
    if (bit) {
        low += split;
        range -= split;
        counts[1]++;
    } else {
        range = split;
        counts[0]++;
    }
}

void put_integer(int value, int off, int ctx) {
    fprintf(stderr, "PUT_INT: value=%d off=%d ctx=%d\n", value, off, ctx);
    int tmp = off;
    value += (1 << tmp);
    while (value >= (1 << (tmp + 1))) {
        put_bit(1, ctx * 99 + tmp + 1);
        tmp++;
    }
    put_bit(0, ctx * 99 + tmp + 1);
    while (tmp--) {
        put_bit((value >> tmp) & 1, ctx);
    }
}

void flush() {
    fprintf(stderr, "FLUSH: low=%lld\n", low);
    for (int i = 0; i < 10; i++) {
        int byte_out = (low / RADIX) + 1;
        if (byte_out > 255) byte_out = 255;
        fprintf(stderr, "FLUSH[%d]: byte=%d\n", i, byte_out);
        putchar(byte_out);
        low = (low % RADIX) * RADIX;
    }
}

int main() {
    unsigned char data[10000];
    int len = fread(data, 1, sizeof(data), stdin);
    fprintf(stderr, "Input: %d bytes\n", len);

    // Literals only - no back-references
    int op_count = len;
    fprintf(stderr, "Operation count: %d\n", op_count);

    put_integer(op_count, 9, 0);

    for (int i = 0; i < len; i++) {
        int c = (int)(signed char)data[i];
        fprintf(stderr, "Literal[%d]: char='%c' value=%d\n", i, data[i], c);
        put_bit(0, 1);  // literal operation
        put_bit(c < 0, 8);  // sign bit
        put_integer(c < 0 ? -c : c, LITSIZE, 9);  // magnitude
    }

    flush();
    fprintf(stderr, "Done\n");
    return 0;
}
EEOF

gcc -O0 encoder_debug.c -o encoder_debug 2>&1
echo "Compilation: $?"
echo ""

# Run encoder with debug output
echo "=== Encoder debug output ==="
./encoder_debug < test_single.txt > test_single.comp 2>encoder_debug.log
echo "Exit: $?"
echo ""

# Show debug log
echo "=== Encoder trace (first 50 lines) ==="
head -50 encoder_debug.log
echo ""

# Show compressed file
echo "=== Compressed file ==="
ls -l test_single.comp
echo ""

# Try to decompress
echo "=== Decompression attempt ==="
cat test_single.comp | ./decomp > test_single_out.txt 2>&1
echo "Exit: $?"
out_size=$(wc -c < test_single_out.txt)
echo "Output: $out_size bytes (expected 1)"
if [ $out_size -gt 0 ]; then
    echo "Content: $(cat test_single_out.txt)"
fi

