#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define RADIX 255
#define OFF1 5
#define OFF2 2
#define LITSIZE 4

int cc[1000000];
unsigned char output[1000000];
int output_len = 0;
long low = 0;
long range = 1;

void normalize() {
    while (range < RADIX) {
        int byte_val = (low / RADIX) + 1;
        if (byte_val > 255) byte_val = 255;
        output[output_len++] = byte_val;

        // Correct formula to maintain synchronization with decoder
        low = (low / RADIX) * (RADIX * RADIX + 1) + (low % RADIX) * RADIX;
        range *= RADIX;
    }
}

void put_bit(int bit, int ctx) {
    normalize();
    int *counts = cc + ctx * 2;
    long split = range * (counts[0] + 1) / (counts[0] + counts[1] + 2);
    if (bit) {
        low += split;
        range -= split;
        counts[1]++;
    } else {
        range = split;
        counts[0]++;
    }
}

void put_integer(int value, int tmp, int ctx) {
    ctx *= 99;
    value += (1 << tmp);

    int bit_len = 0;
    int test = value;
    while (test > 1) {
        test >>= 1;
        bit_len++;
    }

    for (int i = 0; i < bit_len; i++) {
        put_bit(0, tmp + 1 + ctx);
        tmp++;
    }
    put_bit(1, tmp + 1 + ctx);

    for (int i = bit_len - 1; i >= 0; i--) {
        put_bit((value >> i) & 1, ctx);
    }
}

void flush() {
    for (int i = 0; i < 10; i++) {
        int byte_val = (low / RADIX) + 1;
        if (byte_val > 255) byte_val = 255;
        output[output_len++] = byte_val;
        low = (low / RADIX) * (RADIX * RADIX + 1) + (low % RADIX) * RADIX;
    }
}

int find_match(char *data, int pos, int len, int *out_offset, int *out_len) {
    int max_len = 0;
    int best_offset = 0;
    int max_offset = (pos < 200) ? pos : 200;
    int max_match = (len - pos < 63) ? (len - pos) : 63;

    for (int offset = 1; offset <= max_offset; offset++) {
        int match_len = 0;
        while (match_len < max_match && data[pos + match_len] == data[pos - offset + match_len]) {
            match_len++;
        }
        if (match_len > max_len) {
            max_len = match_len;
            best_offset = offset;
        }
    }

    if (max_len >= 2) {
        *out_offset = best_offset;
        *out_len = max_len;
        return 1;
    }
    return 0;
}

void compress(char *data, int len) {
    int ops[10000][3];
    int op_count = 0;

    int pos = 0;
    while (pos < len) {
        int offset, match_len;
        if (find_match(data, pos, len, &offset, &match_len)) {
            ops[op_count][0] = 1;
            ops[op_count][1] = offset - 1;
            ops[op_count][2] = match_len - 1;
            op_count++;
            pos += match_len;
        } else {
            ops[op_count][0] = 0;
            ops[op_count][1] = data[pos];
            op_count++;
            pos++;
        }
    }

    put_integer(op_count, 9, 0);

    for (int i = 0; i < op_count; i++) {
        if (ops[i][0] == 1) {
            put_bit(1, 1);
            put_integer(ops[i][1], OFF1, 2);
            put_integer(ops[i][2], OFF2, 3);
        } else {
            put_bit(0, 1);
            int ch = ops[i][1];
            if (ch < 0) {
                put_bit(1, 8);
                put_integer(-ch, LITSIZE, 9);
            } else {
                put_bit(0, 8);
                put_integer(ch, LITSIZE, 9);
            }
        }
    }

    flush();
}

int main() {
    char data[10000];
    int len = fread(data, 1, sizeof(data), stdin);

    compress(data, len);

    fwrite(output, 1, output_len, stdout);
    return 0;
}

